-- FS-007: installation execution, readiness, acceptance and human launch authorization.
begin;
create table public.furnishing_installation_projects(
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.owners(id),property_id uuid not null references public.properties(id),project_id uuid not null unique references public.furnishing_projects(id) on delete cascade,procurement_baseline_id uuid not null unique references public.furnishing_procurement_baselines(id),
 status text not null default 'planning' check(status in('planning','site_readiness','scheduled','in_progress','punch_list','launch_review','authorized','handed_off','closed','on_hold','cancelled')),version bigint not null default 1 check(version>0),target_start_at timestamptz,target_complete_at timestamptz,timezone text not null,
 source_snapshot jsonb not null,source_hash text not null,idempotency_key text not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_by uuid references public.profiles(id),completed_at timestamptz,unique(workspace_id,idempotency_key)
);
create table public.furnishing_installation_crews(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,name text not null,crew_type text not null check(crew_type in('delivery','assembly','installation','mounting','staging','cleaning','photography','inspection','other')),status text not null default 'active' check(status in('active','inactive')),lead_profile_id uuid references public.profiles(id),contact_snapshot jsonb not null default '{}',created_at timestamptz not null default now());
create table public.furnishing_installation_crew_members(id uuid primary key default gen_random_uuid(),crew_id uuid not null references public.furnishing_installation_crews(id) on delete cascade,profile_id uuid references public.profiles(id),display_name text not null,role text not null,unique(crew_id,display_name));
create table public.furnishing_installation_sessions(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,name text not null,status text not null default 'scheduled' check(status in('draft','scheduled','in_progress','completed','cancelled')),starts_at timestamptz not null,ends_at timestamptz not null,delivery_required boolean not null default false,notes text,version bigint not null default 1,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.furnishing_installation_session_crews(session_id uuid not null references public.furnishing_installation_sessions(id) on delete cascade,crew_id uuid not null references public.furnishing_installation_crews(id),primary key(session_id,crew_id));
alter table public.furnishing_installation_tasks add column if not exists installation_project_id uuid references public.furnishing_installation_projects(id),add column if not exists room_id uuid references public.furnishing_rooms(id),add column if not exists procurement_line_id uuid references public.furnishing_procurement_lines(id),add column if not exists session_id uuid references public.furnishing_installation_sessions(id),add column if not exists task_type text check(task_type is null or task_type in('delivery','assembly','placement','mounting','staging','removal','cleaning','technology','safety','photography','inspection','other')),add column if not exists required boolean not null default true,add column if not exists accepted_quantity numeric(10,2) not null default 0 check(accepted_quantity>=0),add column if not exists blocking_reason text,add column if not exists sort_order integer not null default 0,add column if not exists revision bigint not null default 1,add column if not exists accepted_by uuid references public.profiles(id),add column if not exists accepted_at timestamptz;
alter table public.furnishing_installation_tasks drop constraint if exists furnishing_installation_tasks_status_check;
alter table public.furnishing_installation_tasks add constraint furnishing_installation_tasks_status_check check(status in('pending','blocked','ready','scheduled','in_progress','installed','complete','accepted','damaged','missing','incorrect','deferred','not_required','cancelled'));
create table public.furnishing_installation_task_dependencies(task_id uuid not null references public.furnishing_installation_tasks(id) on delete cascade,depends_on_task_id uuid not null references public.furnishing_installation_tasks(id),primary key(task_id,depends_on_task_id),check(task_id<>depends_on_task_id));
create table public.furnishing_site_readiness_checks(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,category text not null check(category in('access_delivery','utilities','work_areas','safety_protection','technology','operations','photography')),name text not null,description text,required boolean not null default true,status text not null default 'pending' check(status in('pending','passed','failed','waived')),weight numeric(8,4) not null default 1 check(weight>=0),blocking_reason text,verified_by uuid references public.profiles(id),verified_at timestamptz,waiver_reason text,unique(installation_project_id,category,name));
create table public.furnishing_installation_evidence(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,task_id uuid references public.furnishing_installation_tasks(id),readiness_check_id uuid references public.furnishing_site_readiness_checks(id),punch_item_id uuid references public.furnishing_punch_list_items(id),evidence_type text not null check(evidence_type in('photo','document','packing_slip','signoff','note')),storage_path text,caption text,metadata jsonb not null default '{}',captured_by uuid not null references public.profiles(id),captured_at timestamptz not null default now(),check(num_nonnulls(task_id,readiness_check_id,punch_item_id)>=1));
alter table public.furnishing_punch_list_items add column if not exists installation_project_id uuid references public.furnishing_installation_projects(id),add column if not exists room_id uuid references public.furnishing_rooms(id),add column if not exists task_id uuid references public.furnishing_installation_tasks(id),add column if not exists exception_type text check(exception_type is null or exception_type in('damage','missing_item','incorrect_item','workmanship','safety','technology','cleaning','photography','other')),add column if not exists blocking_launch boolean not null default false,add column if not exists source_capability text check(source_capability is null or source_capability in('fs005','fs006','fs007')),add column if not exists source_record_id uuid,add column if not exists resolved_by uuid references public.profiles(id),add column if not exists resolved_at timestamptz;
create table public.furnishing_room_acceptances(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,room_id uuid not null references public.furnishing_rooms(id),status text not null default 'pending' check(status in('pending','conditionally_accepted','accepted','rejected')),task_summary jsonb not null,evidence_summary jsonb not null,punch_summary jsonb not null,notes text,accepted_by uuid references public.profiles(id),accepted_at timestamptz,version bigint not null default 1,unique(installation_project_id,room_id,version));
create table public.furnishing_launch_readiness_assessments(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id) on delete cascade,version bigint not null,policy_version text not null,readiness_percent integer not null check(readiness_percent between 0 and 100),category_results jsonb not null,blockers jsonb not null,ready_for_authorization boolean not null,source_revision bigint not null,assessed_by uuid not null references public.profiles(id),assessed_at timestamptz not null default now(),unique(installation_project_id,version));
create table public.furnishing_launch_authorizations(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),assessment_id uuid not null unique references public.furnishing_launch_readiness_assessments(id),decision text not null check(decision in('authorized','blocked','returned_for_work')),reason text,policy_version text not null,decided_by uuid not null references public.profiles(id),decided_at timestamptz not null default now());
create table public.furnishing_launch_handoffs(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null unique references public.furnishing_installation_projects(id),launch_authorization_id uuid not null unique references public.furnishing_launch_authorizations(id),operations_snapshot jsonb not null,room_snapshot jsonb not null,open_nonblocking_items jsonb not null default '[]',outcome_id uuid,handed_off_by uuid not null references public.profiles(id),handed_off_at timestamptz not null default now());
create table public.furnishing_installation_events(id uuid primary key default gen_random_uuid(),installation_project_id uuid not null references public.furnishing_installation_projects(id),workspace_id uuid not null references public.owners(id),property_id uuid not null references public.properties(id),project_id uuid not null references public.furnishing_projects(id),actor_id uuid not null references public.profiles(id),correlation_id uuid not null,event_type text not null,previous_version bigint,resulting_version bigint,reason text,policy_version text not null,related_type text,related_id uuid,payload jsonb not null default '{}',occurred_at timestamptz not null default now());
create index furnishing_installation_scope_idx on public.furnishing_installation_projects(workspace_id,property_id,status);
create index furnishing_installation_session_schedule_idx on public.furnishing_installation_sessions(installation_project_id,starts_at,ends_at);
create index furnishing_installation_task_room_status_idx on public.furnishing_installation_tasks(installation_project_id,room_id,status);
create index furnishing_site_readiness_status_idx on public.furnishing_site_readiness_checks(installation_project_id,category,status);
create index furnishing_installation_event_timeline_idx on public.furnishing_installation_events(installation_project_id,occurred_at desc);
do $rls$ declare t text;begin foreach t in array array['furnishing_installation_projects','furnishing_installation_crews','furnishing_installation_crew_members','furnishing_installation_sessions','furnishing_installation_session_crews','furnishing_installation_task_dependencies','furnishing_site_readiness_checks','furnishing_installation_evidence','furnishing_room_acceptances','furnishing_launch_readiness_assessments','furnishing_launch_authorizations','furnishing_launch_handoffs','furnishing_installation_events'] loop execute format('alter table public.%I enable row level security',t);end loop;end $rls$;
create policy "Members read installation projects" on public.furnishing_installation_projects for select to authenticated using(public.active_workspace_role(workspace_id)is not null or public.is_admin());
create policy "Members read installation events" on public.furnishing_installation_events for select to authenticated using(public.active_workspace_role(workspace_id)is not null or public.is_admin());
-- Launch decisions and the installation event ledger intentionally have no update/delete policy.
commit;
